<?php
require_once '../config/database.php'; require_once '../includes/auth.php'; require_role('admin');$page_title='Оценки';
if(isset($_GET['delete'])){try{$id=(int)$_GET['delete'];$q=$pdo->prepare('DELETE FROM grades WHERE id=?');$q->execute([$id]);$_SESSION[$q->rowCount()?'flash_success':'flash_error']=$q->rowCount()?'Оценка удалена.':'Оценка не найдена.';}catch(Throwable $e){$_SESSION['flash_error']='Не удалось удалить оценку.';}header('Location:grades.php');exit;}
$groupId=(int)($_GET['group_id']??0);$subjectId=(int)($_GET['subject_id']??0);$search=trim($_GET['q']??'');
$groups=$pdo->query('SELECT id,name FROM groups ORDER BY name')->fetchAll();$subjects=$pdo->query('SELECT id,name FROM subjects ORDER BY name')->fetchAll();
$sql="SELECT gr.*,CONCAT(st.surname,' ',st.name) student_name,g.name group_name,s.name subject_name,CONCAT(COALESCE(t.surname,''),' ',COALESCE(t.name,'')) teacher_name FROM grades gr JOIN students st ON st.id=gr.student_id JOIN groups g ON g.id=st.group_id JOIN subjects s ON s.id=gr.subject_id LEFT JOIN teachers t ON t.id=gr.teacher_id WHERE 1";$params=[];
if($groupId){$sql.=' AND g.id=?';$params[]=$groupId;}if($subjectId){$sql.=' AND s.id=?';$params[]=$subjectId;}if($search!==''){$sql.=' AND (st.surname LIKE ? OR st.name LIKE ? OR s.name LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like);}$sql.=' ORDER BY gr.grade_date DESC,gr.id DESC LIMIT 200';$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
$avg=$pdo->query('SELECT ROUND(AVG(grade),2) FROM grades')->fetchColumn();include '../includes/header.php';?>
<div class="cards"><div class="card"><div class="label">Всего оценок</div><div class="value"><?=$pdo->query('SELECT COUNT(*) FROM grades')->fetchColumn()?></div></div><div class="card"><div class="label">Средний балл</div><div class="value"><?=$avg?:'—'?></div></div></div>
<div class="panel"><form class="filters" method="get"><input name="q" value="<?=htmlspecialchars($search)?>" placeholder="🔍 Студент или предмет"><select name="group_id"><option value="0">Все группы</option><?php foreach($groups as $g):?><option value="<?=$g['id']?>" <?=$groupId==$g['id']?'selected':''?>><?=htmlspecialchars($g['name'])?></option><?php endforeach;?></select><select name="subject_id"><option value="0">Все предметы</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" <?=$subjectId==$s['id']?'selected':''?>><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select><button class="btn">Применить</button><a class="btn secondary" href="grades.php">Сбросить</a></form></div>
<div class="panel" style="margin-top:20px"><div class="table-wrap"><table><tr><th>Дата</th><th>Студент</th><th>Группа</th><th>Предмет</th><th>Оценка</th><th>Преподаватель</th><th>Комментарий</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=date('d.m.Y',strtotime($r['grade_date']))?></td><td><?=htmlspecialchars($r['student_name'])?></td><td><?=htmlspecialchars($r['group_name'])?></td><td><?=htmlspecialchars($r['subject_name'])?></td><td><span class="grade grade-<?=$r['grade']?>"><?=$r['grade']?></span></td><td><?=htmlspecialchars(trim($r['teacher_name']))?:'—'?></td><td><?=htmlspecialchars($r['comment'])?></td><td><a class="btn danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Удалить оценку?')">Удалить</a></td></tr><?php endforeach;?></table></div></div>
<?php include '../includes/footer.php';?>
